/**
 * @deprecated Import `WeekRangePill` from `@joyui/react` (lives under
 * `base/week-range-pill`). This file remains only so old docs path maps
 * resolve; it no longer re-exports to avoid stealing the catalog slug.
 */
export {};

"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import { useState, type ComponentType } from "react";
import {
  RiCheckboxCircleFill,
  RiErrorWarningFill,
  RiInformationFill,
  RiNotification3Fill,
} from "@remixicon/react";
import { WeekRangePill } from "@/components/ui/week-range-pill/week-range-pill";
import { cx } from "@/lib/utils";

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export type AlertFeedItem = {
  icon: IconComponent;
  iconBg: string;
  title: string;
  description: string;
  date: string;
};

export type AlertFeedCardProps = {
  title?: string;
  countLabel?: string;
  count?: number;
  rangeLabel?: string;
  onPrevRange?: () => void;
  onNextRange?: () => void;
  items?: AlertFeedItem[];
  className?: string;
};

const DEFAULT_ITEMS: AlertFeedItem[] = [
  {
    icon: RiErrorWarningFill,
    iconBg: "bg-notification-error-foreground",
    title: "构建失败",
    description: "main 分支 CI 在 typecheck 步骤失败，已通知相关负责人。",
    date: "今天",
  },
  {
    icon: RiInformationFill,
    iconBg: "bg-chart-6",
    title: "依赖更新",
    description: "@joyui/react 有新的补丁版本可用，建议在本周内升级。",
    date: "昨天",
  },
  {
    icon: RiCheckboxCircleFill,
    iconBg: "bg-chart-7-active",
    title: "发布成功",
    description: "docs 站点已部署到生产环境，预览链接已写入变更说明。",
    date: "周一",
  },
  {
    icon: RiNotification3Fill,
    iconBg: "bg-chart-5",
    title: "审批待处理",
    description: "有 2 条设计评审仍在等待你的反馈。",
    date: "周日",
  },
];

/**
 * Scrollable alert / activity feed with an optional week-range header.
 * Formerly ImportantAlertsCard — content is injectable for any vertical.
 */
export function AlertFeedCard({
  title = "重要动态",
  countLabel = "本周",
  count = 12,
  rangeLabel = "本周",
  onPrevRange,
  onNextRange,
  items = DEFAULT_ITEMS,
  className,
}: AlertFeedCardProps = {}) {
  const localize = useTemplateCopy();
  const [scrolled, setScrolled] = useState(false);

  return localize((
    <section
      className={cx(
        "flex h-[330px] w-full min-w-0 flex-col gap-4 overflow-hidden rounded-[20px] border border-border-button-default bg-background-secondary-default px-2.5 pt-2.5 shadow-xs",
        className,
      )}
    >
      <div className="flex w-full items-start justify-between gap-2 px-1.5 pt-1.5">
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          <p className="text-body-medium text-text-secondary">{title}</p>
          <div className="flex items-baseline gap-1">
            <p className="text-title-1-medium whitespace-nowrap text-text-primary tabular-nums">
              {count}
            </p>
            <span className="text-caption-1-medium whitespace-nowrap text-text-secondary">
              {countLabel}
            </span>
          </div>
        </div>
        <WeekRangePill label={rangeLabel} onPrev={onPrevRange} onNext={onNextRange} />
      </div>

      <div className="relative min-h-0 w-full flex-1">
        <div
          className="flex h-full w-full flex-col gap-2.5 overflow-y-auto overscroll-contain pb-2.5"
          onScroll={(e) => setScrolled(e.currentTarget.scrollTop > 0)}
        >
          {items.length === 0 ? (
            <p className="px-2 py-6 text-center text-body-2-regular text-text-tertiary">
              暂无动态
            </p>
          ) : (
            items.map((alert, index) => (
              <div
                key={`${alert.title}-${index}`}
                className="relative flex w-full shrink-0 gap-2.5 rounded-2lg bg-background-inner-default p-2.5 pe-16"
              >
                <span
                  className={cx(
                    "mt-0.5 flex size-8 shrink-0 items-center justify-center rounded-full",
                    alert.iconBg,
                  )}
                >
                  <alert.icon className="size-[18px] text-text-white" aria-hidden />
                </span>
                <div className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <p className="text-body-medium text-text-primary">{alert.title}</p>
                  <p className="text-body-2-regular text-text-secondary">{alert.description}</p>
                </div>
                <span className="absolute top-2.5 end-2.5 rounded-md bg-background-secondary-default px-1.5 py-px text-caption-1-medium whitespace-nowrap text-text-secondary">
                  {alert.date}
                </span>
              </div>
            ))
          )}
        </div>
        <div
          aria-hidden
          className={cx(
            "pointer-events-none absolute inset-x-0 top-0 h-10 bg-linear-to-b from-background-secondary-default to-transparent",
            "transition-opacity duration-200 ease-out",
            scrolled ? "opacity-100" : "opacity-0",
          )}
        />
      </div>
    </section>
  ));
}

"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import {
  RiAddLine,
  RiBriefcaseLine,
  RiMailLine,
  RiMapPinLine,
  RiUserLine,
} from "@remixicon/react";
import type { ComponentType, ReactNode } from "react";
import { Avatar } from "@/components/ui/avatar/avatar";
import { Button } from "@/components/ui/buttons/button";
import { cx } from "@/lib/utils";

type IconComponent = ComponentType<{
  className?: string;
  "aria-hidden"?: boolean | "true" | "false";
}>;

export type ProfileInfoDetail = {
  icon: IconComponent;
  label: string;
  value: string;
};

export type ProfileInfoCardProps = {
  name?: string;
  initials?: string;
  avatarSrc?: string;
  details?: ProfileInfoDetail[];
  onAddPhoto?: () => void;
  /** Extra node under the name (role badge, etc.). */
  subtitle?: ReactNode;
  className?: string;
};

const DEFAULT_DETAILS: ProfileInfoDetail[] = [
  { icon: RiUserLine, label: "角色", value: "产品设计师" },
  { icon: RiBriefcaseLine, label: "团队", value: "Growth" },
  { icon: RiMailLine, label: "邮箱", value: "alex@joyui.dev" },
  { icon: RiMapPinLine, label: "地点", value: "上海" },
];

/**
 * Generic profile card: avatar, name, and a stack of label/value rows.
 * Formerly PatientInfoCard — data is injectable for HR / CRM / health demos.
 */
export function ProfileInfoCard({
  name = "Alex Chen",
  initials = "AC",
  avatarSrc,
  details = DEFAULT_DETAILS,
  onAddPhoto,
  subtitle,
  className,
}: ProfileInfoCardProps = {}) {
  const localize = useTemplateCopy();
  return localize((
    <section
      className={cx(
        "flex h-[330px] w-full min-w-0 flex-col items-center gap-[15px] rounded-[20px] border border-border-button-default bg-background-secondary-default px-2.5 pt-6 pb-2.5 shadow-xs",
        className,
      )}
    >
      <div className="relative">
        <Avatar
          size="lg"
          initials={initials}
          src={avatarSrc}
          className="size-[66px] text-[24.75px]"
        />
        <Button
          variant="secondary"
          size="xs"
          iconOnly
          leadingIcon={RiAddLine}
          aria-label="Add profile photo"
          onClick={onAddPhoto}
          className="absolute -top-0.5 -end-0.5 rounded-full"
        />
      </div>
      <div className="flex flex-col items-center gap-0.5">
        <p className="text-title-2-medium whitespace-nowrap text-text-primary">{name}</p>
        {subtitle ? (
          <div className="text-caption-1-medium text-text-secondary">{subtitle}</div>
        ) : null}
      </div>
      <div className="flex w-full flex-1 flex-col gap-2.5 overflow-y-auto">
        {details.length === 0 ? (
          <p className="px-2 text-center text-body-2-regular text-text-tertiary">暂无资料</p>
        ) : (
          details.map((detail) => (
            <div
              key={detail.label}
              className="flex w-full items-center gap-2 rounded-2lg bg-background-inner-default px-2.5 py-2"
            >
              <div className="flex min-w-0 flex-1 items-center gap-1.5">
                <detail.icon className="size-4 shrink-0 text-text-secondary" aria-hidden />
                <span className="truncate text-body-regular text-text-secondary">
                  {detail.label}
                </span>
              </div>
              <span className="max-w-[45%] shrink-0 truncate text-end text-body-medium text-text-primary">
                {detail.value}
              </span>
            </div>
          ))
        )}
      </div>
    </section>
  ));
}

"use client";

import { useTemplateCopy } from "@/components/ui/template-copy/template-copy";

import { useEffect, useState } from "react";
import { ChevronLeft16, ChevronRight16 } from "@/components/ui/date-picker/shared";
import { cx } from "@/lib/utils";

const NAV_BUTTON = cx(
  "flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-[3px] text-text-secondary outline-none",
  "transition-colors duration-150 ease hover:bg-background-secondary-hover",
  "focus-visible:ring-2 focus-visible:ring-border-focus-ring",
);

function AnimatedLabel({ label }: { label: string }) {
  const localize = useTemplateCopy();
  const [current, setCurrent] = useState(label);
  const [previous, setPrevious] = useState<string | null>(null);

  useEffect(() => {
    if (label !== current) {
      setPrevious(current);
      setCurrent(label);
    }
  }, [label, current]);

  useEffect(() => {
    if (previous === null) return;
    const t = setTimeout(() => setPrevious(null), 240);
    return () => clearTimeout(t);
  }, [previous]);

  return localize((
    <span className="relative flex-1 overflow-hidden text-center text-body-medium whitespace-nowrap text-text-primary">
      <span className="invisible">{current}</span>
      {previous !== null && (
        <span
          key={`out-${previous}`}
          className="animate-label-out absolute inset-0 flex items-center justify-center"
        >
          {previous}
        </span>
      )}
      <span
        key={`in-${current}`}
        className={cx(
          "absolute inset-0 flex items-center justify-center",
          previous !== null && "animate-label-in",
        )}
      >
        {current}
      </span>
    </span>
  ));
}

export type WeekRangePillProps = {
  label: string;
  onPrev?: () => void;
  onNext?: () => void;
  className?: string;
};

/** Compact week / month range chrome with optional prev/next controls. */
export function WeekRangePill({
  label,
  onPrev,
  onNext,
  className,
}: WeekRangePillProps) {
  const localize = useTemplateCopy();
  const interactive = !!(onPrev || onNext);
  return localize((
    <div
      className={cx(
        "flex h-8 min-w-[151px] shrink-0 items-center justify-between gap-1 rounded-2lg border border-border-button-default bg-background-primary-default px-1 py-1 shadow-xs",
        className,
      )}
    >
      {interactive ? (
        <button type="button" aria-label="Previous" onClick={onPrev} className={NAV_BUTTON}>
          <ChevronLeft16 />
        </button>
      ) : (
        <span className="flex size-4 shrink-0 items-center justify-center text-text-secondary" aria-hidden>
          <ChevronLeft16 />
        </span>
      )}
      {interactive ? (
        <AnimatedLabel label={label} />
      ) : (
        <span className="flex-1 text-center text-body-medium whitespace-nowrap text-text-primary">
          {label}
        </span>
      )}
      {interactive ? (
        <button type="button" aria-label="Next" onClick={onNext} className={NAV_BUTTON}>
          <ChevronRight16 />
        </button>
      ) : (
        <span className="flex size-4 shrink-0 items-center justify-center text-text-secondary" aria-hidden>
          <ChevronRight16 />
        </span>
      )}
    </div>
  ));
}
